def find_max(words):
    if not words:
        return ""

    max_unique_count = 0
    result_word = None

    for word in words:
        unique_chars = len(set(word))

        # Check if current word has more unique characters than the best found so far
        if unique_chars > max_unique_count or (unique_chars == max_unique_count and (result_word is None or word < result_word)):
            max_unique_count = unique_chars
            result_word = word

    return result_word
